שמות יד ל-לא, שם טו א-כו

וַיּוֹשַׁע יְיָ בַּיּוֹם הַהוּא אֶת יִשְׂרָאֵל מִיַּד מִצְרָיִם, וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת עַל שְׂפַת הַיָּם׃ וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדֹלָה אֲשֶׁר עָשָׂה יְיָ בְּמִצְרַיִם, וַיִּירְאוּ הָעָם אֶת יְיָ, וַיַּאֲמִינוּ בַּייָ וּבְמֹשֶׁה עַבְדּוֹ׃

אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל אֶת הַשִּׁירָה הַזֹּאת לַייָ, וַיֹּאמְרוּ לֵאמֹר, אָשִׁירָה לַייָ כִּי גָאֹה גָּאָה סוּס וְרֹכְבוֹ רָמָה בַיָּם׃ עָזִּי וְזִמְרָת יָהּ וַיְהִי לִי לִישׁוּעָה, זֶה אֵלִי וְאַנְוֵהוּ, אֱלֹהֵי אָבִי וַאֲרֹמְמֶנְהוּ׃ יְיָ אִישׁ מִלְחָמָה, יְיָ שְׁמוֹ׃ מַרְכְּבֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם, וּמִבְחַר שָׁלִשָׁיו טֻבְּעוּ בְיַם סוּף׃ תְּהֹמֹת יְכַסְיֻמוּ, יָרְדוּ בִמְצוֹלֹת כְּמוֹ אָבֶן׃ יְמִינְךָ יְיָ נֶאְדָּרִי בַּכֹּחַ, יְמִינְךָ יְיָ תִּרְעַץ אוֹיֵב׃ וּבְרֹב גְּאוֹנְךָ תַּהֲרֹס קָמֶיךָ, תְּשַׁלַּח חֲרֹנְךָ יֹאכְלֵמוֹ כַּקַּשׁ׃ וּבְרוּחַ אַפֶּיךָ נֶעֶרְמוּ מַיִם, נִצְּבוּ כְמוֹ נֵד נֹזְלִים, קָפְאוּ תְהֹמֹת בְּלֶב יָם׃ אָמַר אוֹיֵב אֶרְדֹּף אַשִּׂיג אֲחַלֵּק שָׁלָל, תִּמְלָאֵמוֹ נַפְשִׁי, אָרִיק חַרְבִּי, תּוֹרִישֵׁמוֹ יָדִי׃ נָשַׁפְתָּ בְרוּחֲךָ כִּסָּמוֹ יָם, צָלְלוּ כַּעוֹפֶרֶת בְּמַיִם אַדִּירִים׃ מִי כָמֹכָה בָּאֵלִם יְיָ, מִי כָּמֹכָה נֶאְדָּר בַּקֹּדֶשׁ, נוֹרָא תְהִלֹּת עֹשֵׂה פֶלֶא׃ נָטִיתָ יְמִינְךָ תִּבְלָעֵמוֹ אָרֶץ׃ נָחִיתָ בְחַסְדְּךָ עַם זוּ גָּאָלְתָּ, נֵהַלְתָּ בְעָזְּךָ אֶל נְוֵה קָדְשֶׁךָ׃ שָׁמְעוּ עַמִּים יִרְגָּזוּן, חִיל אָחַז יֹשְׁבֵי פְּלָשֶׁת׃ אָז נִבְהֲלוּ אַלּוּפֵי אֱדוֹם, אֵילֵי מוֹאָב יֹאחֲזֵמוֹ רָעַד, נָמֹגוּ כֹּל יֹשְׁבֵי כְנָעַן׃ תִּפֹּל עֲלֵיהֶם אֵימָתָה וָפַחַד, בִּגְדֹל זְרוֹעֲךָ יִדְּמוּ כָּאָבֶן, עַד יַעֲבֹר עַמְּךָ יְיָ, עַד יַעֲבֹר עַם זוּ קָנִיתָ׃ תְּבִאֵמוֹ וְתִטָּעֵמוֹ בְּהַר נַחֲלָתְךָ, מָכוֹן לְשִׁבְתְּךָ פָּעַלְתָּ יְיָ, מִקְּדָשׁ אֲדֹנָי כּוֹנְנוּ יָדֶיךָ׃ יְיָ יִמְלֹךְ לְעֹלָם וָעֶד׃ כִּי בָא סוּס פַּרְעֹה בְּרִכְבּוֹ וּבְפָרָשָׁיו בַּיָּם, וַיָּשֶׁב יְיָ עֲלֵהֶם אֶת מֵי הַיָּם, וּבְנֵי יִשְׂרָאֵל הָלְכוּ בַיַּבָּשָׁה בְּתוֹךְ הַיָּם׃

וַתִּקַּח מִרְיָם הַנְּבִיאָה אֲחוֹת אַהֲרֹן אֶת הַתֹּף בְּיָדָהּ, וַתֵּצֶאןָ כָל הַנָּשִׁים אַחֲרֶיהָ בְּתֻפִּים וּבִמְחֹלֹת׃ וַתַּעַן לָהֶם מִרְיָם, שִׁירוּ לַייָ כִּי גָאֹה גָּאָה, סוּס וְרֹכְבוֹ רָמָה בַיָּם׃    וַיַּסַּע מֹשֶׁה אֶת יִשְׂרָאֵל מִיַּם סוּף וַיֵּצְאוּ אֶל מִדְבַּר שׁוּר, וַיֵּלְכוּ שְׁלֹשֶׁת יָמִים בַּמִּדְבָּר וְלֹא מָצְאוּ מָיִם׃ וַיָּבֹאוּ מָרָתָה, וְלֹא יָכְלוּ לִשְׁתֹּת מַיִם מִמָּרָה כִּי מָרִים הֵם, עַל כֵּן קָרָא שְׁמָהּ מָרָה׃ וַיִּלֹּנוּ הָעָם עַל מֹשֶׁה לֵּאמֹר מַה נִּשְׁתֶּה׃ וַיִּצְעַק אֶל יְיָ וַיּוֹרֵהוּ יְיָ עֵץ וַיַּשְׁלֵךְ אֶל הַמַּיִם וַיִּמְתְּקוּ הַמָּיִם, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ׃ וַיֹּאמֶר, אִם שָׁמוֹעַ תִּשְׁמַע לְקוֹל יְיָ אֱלֹהֶיךָ, וְהַיָּשָׁר בְּעֵינָיו תַּעֲשֶׂה וְהַאֲזַנְתָּ לְמִצְוֹתָיו וְשָׁמַרְתָּ כָּל חֻקָּיו, כָּל הַמַּחֲלָה אֲשֶׁר שַׂמְתִּי בְמִצְרַיִם לֹא אָשִׂים עָלֶיךָ, כִּי אֲנִי יְיָ רֹפְאֶךָ׃

רפאני

רְפָאֵנִי יְיָ וְאֵרָפֵא, הוֹשִׁיעֵנִי וְאִוָּשֵׁעָה, כִּי תְהִלָּתִי אָתָּה׃

וְאָמַרְתָּ בַּיּוֹם הַהוּא, אוֹדְךָ יְיָ כִּי אָנַפְתָּ בִּי, יָשֹׁב אַפְּךָ וּתְנַחֲמֵנִי׃

הִנֵּה אֵל יְשׁוּעָתִי אֶבְטַח וְלֹא אֶפְחָד, כִּי עָזִּי וְזִמְרָת יָהּ יְיָ, וַיְהִי לִי לִישׁוּעָה׃

וּשְׁאַבְתֶּם מַיִם בְּשָׂשׂוֹן מִמַּעַיְנֵי הַיְשׁוּעָה׃

וַאֲמַרְתֶּם בַּיּוֹם הַהוּא, הוֹדוּ לַייָ קִרְאוּ בִשְׁמוֹ, הוֹדִיעוּ בָעַמִּים עֲלִילֹתָיו, הַזְכִּירוּ כִּי נִשְׂגָּב שְׁמוֹ׃

אֱלֹהֵי צוּרִי אֶחֱסֶה בּוֹ, מָגִנִּי וְקֶרֶן יִשְׁעִי מִשְׂגַּבִּי וּמְנוּסִי מֹשִׁעִי מֵחָמָס תֹּשִׁעֵנִי׃

מְהֻלָּל אֶקְרָא יְיָ וּמֵאֹיְבַי אִוָּשֵׁעַ׃

כִּי פָדָה יְיָ אֶת יַעֲקֹב וּגְאָלוֹ מִיַּד חָזָק מִמֶּנּוּ׃

עַל כֵּן אוֹדְךָ יְיָ בַּגּוֹיִם, וּלְשִׁמְךָ אֲזַמֵּר׃

זַמְּרוּ יְיָ כִּי גֵאוּת עָשָׂה, מוּדַעַת זֹאת בְּכָל הָאָרֶץ׃

צַהֲלִי וָרֹנִּי יוֹשֶׁבֶת צִיּוֹן, כִּי גָדוֹל בְּקִרְבֵּךְ קְדוֹשׁ יִשְׂרָאֵל׃

וְאָמַר בַּיּוֹם הַהוּא, הִנֵּה אֱלֹהֵינוּ זֶה קִוִּינוּ לוֹ וְיוֹשִׁיעֵנוּ, זֶה יְיָ קִוִּינוּ לוֹ, נָגִילָה וְנִשְׂמְחָה בִּישׁוּעָתוֹ׃

כִּי לַייָ הַמְּלוּכָה וּמֹשֵׁל בַּגּוֹיִם׃

וְעָלוּ מוֹשִׁעִים בְּהַר צִיּוֹן לִשְׁפֹּט אֶת הַר עֵשָׂו, וְהָיְתָה לַייָ הַמְּלוּכָה׃

וְהָיָה יְיָ לְמֶלֶךְ עַל כָּל הָאָרֶץ, בַּיּוֹם הַהוּא יִהְיֶה יְיָ אֶחָד, וּשְׁמוֹ אֶחָד׃

יְהִי שֵׁם יְיָ מְבֹרָךְ מֵעַתָּה וְעַד עוֹלָם׃

מִמִּזְרַח שֶׁמֶשׁ עַד מְבוֹאוֹ מְהֻלָּל שֵׁם יְיָ׃

לִישׁוּעָתְךָ קִוִּיתִי יְיָ׃

ישתבח

יִשְׁתַּבַּח שִׁמְךָ לָעַד מַלְכֵּנוּ, הַמֶּלֶךְ הַגָּדוֹל וְהַקָּדוֹשׁ בַּשָּׁמַיִם וּבָאָרֶץ. כִּי לְךָ נָאֶה יְיָ אֱלֹהֵינוּ שִׁיר וּשְׁבָח, הַלֵּל וְזִמְרָה, בְּרָכוֹת וְהוֹדָאוֹת, נֵצַח וּגְבוּרָה, גְּדֻלָּה תְּהִלָּה וְתִפְאֶרֶת עֹז וּמַלְכוּת וּמֶמְשָׁלָה, מֵעַתָּה וְעַד עוֹלָם. בָּרוּךְ אַתָּה יְיָ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, מֶלֶךְ גְּדוֹל הַתֻּשְׁבָּחוֹת, אֵל הַהוֹדָאוֹת, אֲדוֹן כָּל הַמַּעֲשִׂים. הַבּוֹחֵר בְּשִׁירֵי זִמְרָה, חַי הָעוֹלָמִים.
""".trimIndent()

