קריאת שמע וברכותיה

ברכה ראשונה

בָּרוּךְ אַתָּה יְהוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, יוֹצֵר אוֹר וּבוֹרֵא חֹשֶׁךְ עוֹשֶׂה שָׁלוֹם וּבוֹרֵא אֶת הַכֹּל; הַמֵּאִיר לָאָרֶץ וְלַדָּרִים עָלֶיהָ, הַמְחַדֵּשׁ בְּכָל יוֹם תָּמִיד מַעֲשֵׂה בְרֵאשִׁית. מָה רַבּוּ מַעֲשֶׂיךָ יְהוָה, כֻּלָּם בְּחָכְמָה עָשִׂיתָ; מָלְאָה הָאָרֶץ, קִנְיָנֶיךָ. הַמֶּלֶךְ הַמְּרוֹמָם שְׁמוֹ לְבַדּוֹ מֵאָז, הַמְּשֻׁבָּח הַמְּפֹאָר הַמִּתְנַשֵּׂא וְטוֹב מִיְּמוֹת עוֹלָם. אֱלֹהֵי עוֹלָם מַלְכֵּנוּ, בְּרַחֲמֶיךָ הָרַבִּים רַחֵם עָלֵינוּ, אֲדוֹן עֻזֵּנוּ צוּר מִשְׂגַּבֵּנוּ, מָגֵן יִשְׁעֵנוּ מִשְׂגָּב בַּעֲדֵנוּ. אֵל בָּרוּךְ גְּדוֹל דֵּעָה הִתְקִין וּפָעַל זָהֳרֵי חַמָּה, טוֹב יָצַר כָּבוֹד לִשְׁמוֹ, מְאוֹרוֹת נָתַן סְבִיבוֹת עֻזּוֹ, פִּנּוֹת צִבְאוֹת קְדוֹשִׁים רוֹמְמֵי שַׁדַּי תָּמִיד יְסַפְּרוּ לָאֵל קְדֻשָּׁתוֹ. תִּתְבָּרַךְ יְהוָה אֱלֹהֵינוּ, בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת; וְעַל כָּל שְׁבָח מַעֲשֵׂה יָדֶיךָ, וּמְאוֹרוֹת אֲשֶׁר יָצַרְתָּ--הֵמָּה יְפָאֲרוּךָ, סֶלָה. תִּתְבָּרַךְ לָעַד צוּרֵנוּ, מַלְכֵּנוּ, גּוֹאֲלֵנוּ, בּוֹרֵא קְדוֹשִׁים. יִשְׁתַּבַּח שִׁמְךָ לָעַד מַלְכֵּנוּ, יוֹצֵר מְשָׁרְתִים, אֲשֶׁר מְשָׁרְתָיו עוֹמְדִים בְּרוּם עוֹלָם, וּמַשְׁמִיעִים אֶת קוֹלָם יַחַד בְּדִבְרֵי אֱלֹהִים חַיִּים וּמֶלֶךְ עוֹלָם. כֻּלָּם אֲהוּבִים, כֻּלָּם בְּרוּרִים, כֻּלָּם גִּבּוֹרִים, עוֹשִׂים בְּאֵימָה רְצוֹן קוֹנֵיהֶם בְּאַהֲבָה. כֻּלָּם מְקַבְּלִים עֲלֵיהֶם עֹל מַלְכוּת שָׁמַיִם זֶה מִזֶּה, וְנוֹתְנִים רְשׁוּת זֶה לָזֶה לְהַקְדִּישׁ לְצוּרָם בְּנַחַת רוּחַ, בְּשָׂפָה בְּרוּרָה, וּבִנְעִימָה טְהוֹרָה. כֻּלָּם כְּאֶחָד עוֹנִים בְּיִרְאָה, וְאוֹמְרִים: קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ יְהוָה צְבָאוֹת; מְלֹא כָל-הָאָרֶץ, כְּבוֹדוֹ. וְהָאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ, יַחַד מִתְנַשְּׂאִים לְעֻמָּתָם: מְשַׁבְּחִים וְאוֹמְרִים--בָּרוּךְ כְּבוֹד-יְהוָה, מִמְּקוֹמוֹ. לְאֵל בָּרוּךְ נְעִימוֹת יִתֵּנוּ, לְמֶלֶךְ אֵל חַי וְקַיָּם זְמִירוֹת יֹאמֵרוּ וְתֻשְׁבָּחוֹת יַשְׁמִיעוּ, כִּי הוּא לְבַדּוֹ פּוֹעֵל גְּבוּרוֹת עוֹשֶׂה חֲדָשׁוֹת זוֹרֵעַ צְדָקוֹת מַצְמִיחַ יְשׁוּעוֹת, אֲדוֹן נִפְלָאוֹת מְחַדֵּשׁ בְּכָל יוֹם תָּמִיד מַעֲשֵׂה בְרֵאשִׁית--כָּאָמוּר לְעֹשֵׂה, אוֹרִים גְּדֹלִים: כִּי לְעוֹלָם חַסְדּוֹ--, הִתְקַנְתָּ מְאוֹרוֹת, לְשַׂמֵּחַ עוֹלָם. בָּרוּךְ אַתָּה יְהוָה, יוֹצֵר הַמְּאוֹרוֹת.

ברכה שנייה

אַהֲבַת עוֹלָם אֲהַבְתָּנוּ, יְהוָה אֱלֹהֵינוּ; חֶמְלָה גְדוֹלָה יְתֵרָה, חָמַלְתָּ עָלֵינוּ. אָבִינוּ מַלְכֵּנוּ, בַּעֲבוּר שְׁמָךְ וּבַעֲבוּר אֲבוֹתֵינוּ אֲשֶׁר בָּטְחוּ בָךְ, וַתְּלַמְּדֵנוּ חֻקֵּי חַיִּים, כֵּן תְּחָנֵּנוּ אָבִינוּ אָב הָרַחֲמָן. הַמְרַחֵם רַחֵם נָא עָלֵינוּ, וְתֶן בְּלִבֵּנוּ לְהָבִין לְהַשְׂכִּיל לִשְׁמֹעַ לִלְמֹד וּלְלַמֵּד לִשְׁמֹר וְלַעֲשׂוֹת וּלְקַיֵּם אֶת כָּל דִּבְרֵי תַלְמוּד תּוֹרָתְךָ בְּאַהֲבָה; וְהָאֵר עֵינֵינוּ בְּמִצְווֹתֶיךָ וְדַבֵּק בְּלִבֵּנוּ יִרְאָתֶךָ, וְיַחֵד לְבָבֵנוּ לְאַהֲבָה אֶת שְׁמֶךָ. וּמְלֹךְ עָלֵינוּ מְהֵרָה אַתָּה לְבַדֶּךָ, כִּי שֵׁם קָדְשְׁךָ בֱּאֱמֶת נִקְרָא עָלֵינוּ; בַּעֲבוּר שְׁמָךְ הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא, מְהֵרָה בְּאַהֲבָה תָרִים קַרְנֵנוּ וְתוֹשִׁיעֵנוּ לְמַעַן שְׁמֶךָ. בָּךְ בָּטַחְנוּ לֹא נֵבוֹשׁ, וּבְשִׁמְךָ חָסִינוּ לֹא נִכָּלֵם וְלֹא נִכָּשֵׁל עַד עוֹלְמֵי עַד: כִּי אָבִינוּ מַלְכֵּנוּ אָתָּה, נָגִילָה וְנִשְׂמְחָה בִּישׁוּעָתֶךָ. רַחֲמֶיךָ יְהוָה אֱלֹהֵינוּ וַחֲסָדֶיךָ, אַל יַעַזְבוּנוּ נֵצַח סֶלָה וָעֶד; וְהָבֵא עָלֵינוּ בְּרָכָה וְשָׁלוֹם מֵאַרְבַּע כַּנְפוֹת הָאָרֶץ, וְהוֹלִיכֵנוּ מְהֵרָה קוֹמְמִיּוּת לְאַרְצֵנוּ. כִּי בָנוּ בָחַרְתָּ מִכָּל עָם וְלָשׁוֹן, וְקֵרַבְתָּנוּ לְשִׁמְךָ הַגָּדוֹל, לְהוֹדוֹת לָךְ וּלְיַחֲדָךְ וּלְרוֹמְמָךְ, וּלְאַהֲבָה אֶת שְׁמָךְ. בָּרוּךְ אַתָּה יְהוָה, הַבּוֹחֵר בְּעַמּוֹ יִשְׂרָאֵל בְּאַהֲבָה.

קריאת שמע

שְׁמַע יִשְׂרָאֵל יְיָ אֱלֹהֵינוּ יְיָ אֶחָד:

בלחש: בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד:

וְאָהַבְתָּ אֵת יהוה אֱלֹהֶיךָ בְּכָל-לְבָבְךָ וּבְכָל נַפְשְׁךָ וּבְכָל מְאֹדֶךָ: וְהָיוּ הַדְּבָרִים הָאֵלֶּה אֲשֶׁר אָנֹכִי מְצַוְּךָ הַיּוֹם. עַל-לְבָבֶךָ: וְשִׁנַּנְתָּם לְבָנֶיךָ וְדִבַּרְתָּ בָּם. בְּשִׁבְתְּךָ בְּבֵיתֶךָ וּבְלֶכְתְּךָ בַדֶּרֶךְ וּבְשָׁכְבְּךָ וּבְקוּמֶךָ: וּקְשַׁרְתָּם לְאוֹת עַל יָדֶךָ. וְהָיוּ לְטֹטָפֹת בֵּין עֵינֶיךָ: וּכְתַבְתָּם עַל מְזֻזוֹת בֵּיתֶךָ וּבִשְׁעָרֶיךָ:

וְהָיָה אִם שָׁמֹעַ תִּשְׁמְעוּ אֶל מִצְוֹתַי אֲשֶׁר אָנֹכִי מְצַוֶּה אֶתְכֶם הַיּוֹם לְאַהֲבָה אֶת יהוה אֱלֹהֵיכֶם וּלְעָבְדוֹ בְּכָל-לְבַבְכֶם וּבְכָל נַפְשְׁכֶם: וְנָתַתִּי מְטַר אַרְצְכֶם בְּעִתּוֹ יוֹרֶה וּמַלְקוֹשׁ וְאָסַפְתָּ דְגָנֶךָ וְתִירֹשְׁךָ וְיִצְהָרֶךָ: וְנָתַתִּי עֵשֶׂב בְּשָׂדְךָ לִבְהֶמְתֶּךָ וְאָכַלְתָּ וְשָׂבָעְתָּ: הִשָּׁמְרוּ לָכֶם פֶּן יִפְתֶּה לְבַבְכֶם וְסַרְתֶּם וַעֲבַדְתֶּם אֱלֹהִים אֲחֵרִים וְהִשְׁתַּחֲוִיתֶם לָהֶם: וְחָרָה אַף יהוה בָּכֶם וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר וְהָאֲדָמָה לֹא תִתֵּן אֶת יְבוּלָהּ וַאֲבַדְתֶּם-מְהֵרָה מֵעַל הָאָרֶץ הַטֹּבָה אֲשֶׁר יהוה נֹתֵן לָכֶם: וְשַׂמְתֶּם אֶת דְּבָרַי אֵלֶּה עַל-לְבַבְכֶם וְעַל נַפְשְׁכֶם וּקְשַׁרְתֶּם אֹתָם לְאוֹת עַל יֶדְכֶם וְהָיוּ לְטוֹטָפֹת בֵּין עֵינֵיכֶם: וְלִמַּדְתֶּם אֹתָם אֶת בְּנֵיכֶם לְדַבֵּר בָּם בְּשִׁבְתְּךָ בְּבֵיתֶךָ וּבְלֶכְתְּךָ בַדֶּרֶךְ וּבְשָׁכְבְּךָ וּבְקוּמֶךָ: וּכְתַבְתָּם עַל מְזוּזוֹת בֵּיתֶךָ וּבִשְׁעָרֶיךָ: לְמַעַן יִרְבּוּ יְמֵיכֶם וִימֵי בְנֵיכֶם עַל הָאֲדָמָה אֲשֶׁר נִשְׁבַּע יהוה לַאֲבֹתֵיכֶם לָתֵת לָהֶם כִּימֵי הַשָּׁמַיִם עַל הָאָרֶץ:

וַיֹאמֶר יהוה אֶל משֶׁה לֵּאמֹר: דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵהֶם וְעָשׂוּ לָהֶם צִיצִת עַל כַּנְפֵי בִגְדֵיהֶם לְדֹרֹתָם וְנָתְנוּ עַל צִיצִת הַכָּנָף פְּתִיל תְּכֵלֶת וְהָיָה לָכֶם לְצִיצִת וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת כָּל מִצְוֹת יהוה וַעֲשִׂיתֶם אֹתָם וְלֹא תָתוּרוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עֵינֵיכֶם אֲשֶׁר אַתֶּם זֹנִים אַחֲרֵיהֶם: לְמַעַן תִּזְכְּרוּ וַעֲשִׂיתֶם אֶת כָּל מִצְוֹתָי וִהְיִיתֶם קְדשִׁים לֵאלֹהֵיכֶם: אֲנִי יהוה אֱלֹהֵיכֶם אֲשֶׁר הוֹצֵאתִי אֶתְכֶם-מֵאֶרֶץ מִצְרַיִם לִהְיוֹת לָכֶם לֵאלֹהִים אֲנִי יהוה אֱלֹהֵיכֶם: אֱמֶת:

ברכה שלישית

אֱמֶת וְיַצִּיב, נָכוֹן וְקַיָּם, יָשָׁר וְנֶאֱמָן, אָהוּב וְחַבִּיב, נֶחְמָד וְנָעִים, נוֹרָא וְאַדִּיר, מְתֻקָּן וּמְקֻבָּל, טוֹב וְיָפֶה הַדָּבָר הַזֶּה עָלֵינוּ--לְעוֹלָם וָעֶד. אֱמֶת--אֱלֹהֵי עוֹלָם מַלְכֵּנוּ, צוּר יַעֲקֹב מָגֵן יִשְׁעֵנוּ; לְדוֹר וָדוֹר הוּא קַיָּם וּשְׁמוֹ קַיָּם, כִּסְאוֹ נָכוֹן וּמַלְכוּתוֹ וֶאֱמוּנָתוֹ קַיֶּמֶת. וּדְבָרָיו חַיִּים וְנֶאֱמָנִים לָעַד, וּלְעוֹלְמֵי עוֹלָמִים: עָלֵינוּ וְעַל אֲבוֹתֵינוּ, עַל בָּנֵינוּ וְעַל כָּל דּוֹרוֹתֵינוּ; עַל הָרִאשׁוֹנִים, וְעַל הָאַחֲרוֹנִים--דָּבָר טוֹב וְקַיָּם בֶּאֱמֶת, חֹק וְלֹא יַעֲבֹר. אֱמֶת--שֶׁאַתָּה הוּא יְהוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, מַלְכֵּנוּ וּמֶלֶךְ אֲבוֹתֵינוּ, גּוֹאֲלֵנוּ וְגוֹאֵל אֲבוֹתֵינוּ, יוֹצְרֵנוּ וְצוּר יְשׁוּעָתֵנוּ, פּוֹדֵנוּ וּמַצִּילֵנוּ מֵעוֹלָם הוּא שְׁמֶךָ, וְאֵין לָנוּ אֱלֹהִים עוֹד זוּלָתֶךָ. עֶזְרַת אֲבוֹתֵינוּ אַתָּה הוּא מֵעוֹלָם, מָגֵן וּמוֹשִׁיעַ לִבְנֵיהֶם אַחֲרֵיהֶם בְּכָל דּוֹר וָדוֹר. בְּרוּם עוֹלָם מוֹשָׁבֶךָ, וּמִשְׁפָּטֶיךָ וְצִדְקָתְךָ עַד אַפְסֵי אָרֶץ. אֱמֶת--אַשְׁרֵי אִישׁ אֲשֶׁר יִשְׁמַע אֶל מִצְווֹתֶיךָ, וְתוֹרָתְךָ וּדְבָרְךָ יָשִׂים עַל לִבּוֹ; אֱמֶת--אַתָּה הוּא אָדוֹן לְעַמָּךְ, וּמֶלֶךְ גִּבּוֹר לָרִיב רִיבָם לְאָבוֹת וּבָנִים; אֱמֶת--אַתָּה הוּא רִאשׁוֹן וְאַתָּה הוּא אַחֲרוֹן, וּמִבַּלְעָדֶיךָ אֵין לָנוּ מוֹשִׁיעַ. אֱמֶת--מִמִּצְרַיִם גְּאַלְתָּנוּ, יְהוָה אֱלֹהֵינוּ: מִבֵּית עֲבָדִים פְּדִיתָנוּ, וְכָל בְּכוֹרֵי מִצְרַיִם בַּדֶּבֶר הָרַגְתָּ, וּבְכוֹרְךָ גָּאַלְתָּ, וְיַם סוּף בָּקַעְתָּ, וְזֵדִים טִבַּעְתָּ, וִידִידִים עָבְרוּ מִיָּם, וַיְכַסּוּ מַיִם צָרֵיהֶם עַד אֶחָד מֵהֶם לֹא נוֹתָר. וְעַל זֹאת שִׁבְּחוּ גְאוּלִים, וְרוֹמְמוּ לָאֵל; וְנָתְנוּ יְדִידִים שִׁירוֹת זְמִירוֹת, תֻּשְׁבָּחוֹת לְמֶלֶךְ אֵל חַי וְקַיָּם. רָם וְנִשָּׂא, גָּדוֹל גִּבּוֹר וְנוֹרָא, מַשְׁפִּיל גֵּאִים, עֲדֵי אָרֶץ. מַגְבִּיהַּ שְׁפָלִים עַד מָרוֹם, מוֹצִיא אֲסִירִים, וּפוֹדֶה עֲנָוִים, וְעוֹזֵר דַּלִּים, וְעוֹנֶה לְעַמּוֹ יִשְׂרָאֵל בְּעֵת שַׁוְּעָם אֵלָיו; תְּהִלָּה לְאֵל עֶלְיוֹן, בָּרוּךְ הוּא. מֹשֶׁה וְכָל בְּנֵי יִשְׂרָאֵל, לְךָ אָמְרוּ שִׁירָה--בְּשִׂמְחָה רַבָּה, אָמְרוּ כֻלָּם: מִי-כָמֹכָה בָּאֵלִם יְהוָה, מִי כָּמֹכָה נֶאְדָּר בַּקֹּדֶשׁ; נוֹרָא תְהִלֹּת, עֹשֵׂה פֶלֶא. יְהוָה יִמְלֹךְ, לְעֹלָם וָעֶד. וְנֶאֱמָר גֹּאֲלֵנוּ, יְהוָה צְבָאוֹת שְׁמוֹ--קְדוֹשׁ, יִשְׂרָאֵל. בָּרוּךְ אַתָּה יְהוָה, גָּאַל יִשְׂרָאֵל.
